import { MINT_EXPORT_SEARCH_INDEX_PATH } from '@mintlify/common';
import fse from 'fs-extra';
import os from 'os';
import path from 'path';
import { extractSearchDocuments, getSearchablePages, writeSearchIndex, } from '../local-preview/export-search.js';
const page = (title, body, description = '') => `<!DOCTYPE html><html><head>
<meta name="description" content="${description}"/></head><body>
<nav><a href="/other">Sidebar link</a></nav>
<h1 id="page-title">${title}</h1>
<div id="content" data-page-title="${title}">${body}</div>
<footer>Footer text</footer>
</body></html>`;
const nav = (value) => value;
const config = (value) => value;
describe('extractSearchDocuments', () => {
    it('splits content into sections at headings with ids', () => {
        const documents = extractSearchDocuments(page('Configuration', '<p>Intro text.</p><h2 id="install"><a href="#install">​</a>Install</h2><p>Run <code>npm i</code>.</p>' +
            '<h2 id="_R_abc_">Card title</h2><p>Card body.</p><h3 id="flags">Flags</h3><ul><li>--port</li><li>--host</li></ul>' +
            '<button>Copy</button><script>ignored()</script><span aria-hidden="true">hidden</span>', 'Configure Conduit'), '/guides/configuration', { breadcrumbs: ['Guides'], version: 'v2' });
        expect(documents).toEqual([
            {
                id: '/guides/configuration#0.0',
                page: '/guides/configuration',
                title: 'Configuration',
                header: 'Configuration',
                content: 'Configure Conduit Intro text.',
                breadcrumbs: ['Guides'],
                version: 'v2',
            },
            {
                id: '/guides/configuration#1.0',
                page: '/guides/configuration',
                title: 'Configuration',
                header: 'Install',
                hash: 'install',
                content: 'Run npm i. Card title Card body.',
                breadcrumbs: ['Guides'],
                version: 'v2',
            },
            {
                id: '/guides/configuration#2.0',
                page: '/guides/configuration',
                title: 'Configuration',
                header: 'Flags',
                hash: 'flags',
                content: '--port --host',
                breadcrumbs: ['Guides'],
                version: 'v2',
            },
        ]);
    });
    it('splits long sections into uniquely identified, overlapping chunks so their full text stays searchable', () => {
        const words = Array.from({ length: 900 }, (_, i) => `w${i}`).join(' ');
        const body = `<h2 id="install">Install</h2><p>${words} lastword</p>` +
            '<h2 id="install-1">Install</h2><p>Again.</p>';
        const documents = extractSearchDocuments(page('Long', body), '/long').slice(1);
        expect(documents.map((document) => [document.id, document.hash])).toEqual([
            ['/long#1.0', 'install'],
            ['/long#1.1', 'install'],
            ['/long#1.2', 'install'],
            ['/long#2.0', 'install-1'],
        ]);
        expect(documents.every((document) => document.content.length <= 2000)).toBe(true);
        expect(documents[2]?.content.endsWith('lastword')).toBe(true);
        expect(documents[1]?.content.split(' ')[0]).toBe(documents[0]?.content.split(' ').at(-1));
        expect(documents[2]?.content.split(' ')[0]).toBe(documents[1]?.content.split(' ').at(-1));
    });
    it('falls back to the content area on API pages and keeps table cells apart', () => {
        const html = `<html><head><meta name="description" content="List users"/></head><body>
<div id="content-area"><h1 id="page-title">Get users</h1>
<h2 id="params">Params</h2><table><tr><th>Name</th><th>Type</th></tr><tr><td>limit</td><td>integer</td></tr></table>
</div></body></html>`;
        expect(extractSearchDocuments(html, '/api/users')).toEqual([
            expect.objectContaining({ header: 'Get users', content: 'List users Get users' }),
            expect.objectContaining({ hash: 'params', content: 'Name Type limit integer' }),
        ]);
    });
    it('returns nothing for pages without a content region', () => {
        expect(extractSearchDocuments('<html><body><p>404</p></body></html>', '/missing')).toEqual([]);
    });
});
describe('getSearchablePages', () => {
    it('tags pages with breadcrumbs, language and version', () => {
        const pages = getSearchablePages(nav({
            languages: [
                {
                    language: 'en',
                    versions: [
                        {
                            version: 'v2',
                            groups: [{ group: 'Start', pages: [{ href: '/quickstart', title: 'Quickstart' }] }],
                        },
                    ],
                },
                {
                    language: 'fr',
                    groups: [{ group: 'Début', pages: [{ href: '/fr/quickstart', title: 'Démarrage' }] }],
                },
            ],
        }), config({
            navigation: {
                languages: [
                    {
                        language: 'en',
                        versions: [
                            {
                                version: 'v2',
                                tabs: [{ tab: 'Docs', groups: [{ group: 'Start', pages: ['quickstart'] }] }],
                            },
                        ],
                    },
                    { language: 'fr', groups: [{ group: 'Début', pages: ['fr/quickstart'] }] },
                ],
            },
        }), undefined);
        expect(pages.get('/quickstart')).toEqual({
            breadcrumbs: ['Docs', 'Start'],
            locale: 'en',
            version: 'v2',
        });
        expect(pages.get('/fr/quickstart')).toEqual({ breadcrumbs: ['Début'], locale: 'fr' });
    });
    it('leaves out pages that hosted search leaves out', () => {
        const generatedNav = nav({
            groups: [
                {
                    group: 'Guides',
                    pages: [
                        { href: '/visible', title: 'Visible' },
                        { href: '/hidden', title: 'Hidden', hidden: true },
                        { href: '/noindex', title: 'Noindex', noindex: true },
                        { href: '/unsearchable', title: 'Unsearchable', searchable: false },
                        { href: '/admin', title: 'Admin', groups: ['admin'] },
                    ],
                },
            ],
        });
        expect([...getSearchablePages(generatedNav, undefined, undefined).keys()]).toEqual([
            '/visible',
        ]);
        expect([...getSearchablePages(generatedNav, undefined, ['admin']).keys()]).toEqual([
            '/visible',
            '/admin',
        ]);
        expect([
            ...getSearchablePages(generatedNav, config({ seo: { indexing: 'all' } }), undefined).keys(),
        ]).toEqual(['/visible', '/hidden']);
    });
});
describe('writeSearchIndex', () => {
    let exportDir;
    beforeEach(async () => {
        exportDir = await fse.mkdtemp(path.join(os.tmpdir(), 'mint-export-search-test-'));
    });
    afterEach(async () => {
        await fse.remove(exportDir);
    });
    it('indexes each searchable exported page once and links /index pages to their parent', async () => {
        await fse.outputFile(path.join(exportDir, 'index', 'index.html'), page('Introduction', '<p>Welcome.</p>'));
        await fse.outputFile(path.join(exportDir, 'quickstart', 'index.html'), page('Quickstart', '<p>Install.</p>'));
        await fse.outputFile(path.join(exportDir, 'secret', 'index.html'), page('Secret', '<p>Hidden.</p>'));
        const count = await writeSearchIndex(exportDir, {
            generatedNav: nav({
                groups: [
                    {
                        group: 'Getting started',
                        pages: [
                            { href: '/index', title: 'Introduction' },
                            { href: '/quickstart', title: 'Quickstart' },
                            { href: '/missing', title: 'Missing' },
                            { href: '/secret', title: 'Secret', noindex: true },
                        ],
                    },
                ],
            }),
            docsConfig: config({
                navigation: {
                    groups: [
                        { group: 'Getting started', pages: ['index', 'quickstart', 'missing', 'secret'] },
                    ],
                },
            }),
            groups: undefined,
        });
        const documents = await fse.readJson(path.join(exportDir, MINT_EXPORT_SEARCH_INDEX_PATH));
        expect(count).toBe(2);
        expect(documents).toEqual([
            expect.objectContaining({
                page: '/',
                title: 'Introduction',
                breadcrumbs: ['Getting started'],
            }),
            expect.objectContaining({
                page: '/quickstart',
                title: 'Quickstart',
                breadcrumbs: ['Getting started'],
            }),
        ]);
    });
    it('writes an empty index when there is no generated navigation', async () => {
        const count = await writeSearchIndex(exportDir, {
            generatedNav: undefined,
            docsConfig: undefined,
            groups: undefined,
        });
        expect(count).toBe(0);
        expect(await fse.readJson(path.join(exportDir, MINT_EXPORT_SEARCH_INDEX_PATH))).toEqual([]);
    });
});
